"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[402],{2402:function(e){e.exports=JSON.parse('{"Lg":[{"name":"Prof. Marco Rasponi","role":"Full Professor","email":"marco.rasponi@polimi.it","bio":"Full Professor at DEIB, Politecnico di Milano. Founder and director of the MiMic Lab, co-founder of BiomimX. Expert in microfluidic technologies and organs-on-chip.","bioFull":"Marco Rasponi is Full Professor at the Department of Electronics, Information and Bioengineering (DEIB) of Politecnico di Milano. He received his Master\'s degree in Biomedical Engineering from Politecnico di Milano (2002) and his PhD in Mechanical Engineering (2006) focused on bioMEMS design. After completing his doctorate, he joined the Massachusetts Institute of Technology as a postdoctoral fellow, where he gained expertise in experimental microfluidics.\\n\\nIn 2008, thanks to a Fondazione Cariplo research grant, he returned to Politecnico di Milano to establish independent research on microfabrication and microfluidics applied to cell culture and regenerative medicine. In 2011 he founded the MiMic (Microfluidics and Biomimetic Microsystems) Laboratory, which he currently leads, supervising PhD students and coordinating several national and international research projects on organ-on-chip applications. In 2017 he co-founded BiomimX, a Politecnico di Milano spin-off company developing beating organs-on-chip.\\n\\nHis main scientific interests focus on the development of microfluidic technologies as advanced tools in the fields of cell and tissue bioengineering, particularly on microscale 3D cell cultures and organs-on-chip as advanced in vitro patho-physiological models.","image":"/images/team/marco-rasponi.jpg","scopusId":"13411181100","orcid":"0000-0002-2904-8652","linkedin":"https://www.linkedin.com/in/marcorasponi/"},{"name":"Prof. Paola Occhetta","role":"Associate Professor","email":"paola.occhetta@polimi.it","bio":"Associate Professor at DEIB, Politecnico di Milano, and CEO & co-founder of BiomimX. Expert in organ-on-chip platforms integrating microfluidics, complex cell culture and AI for disease modelling and drug development.","bioFull":"Paola Occhetta is Associate Professor at the Department of Electronics, Information and Bioengineering (DEIB) of Politecnico di Milano, and CEO & co-founder of BiomimX, a Politecnico di Milano spin-off company developing beating organs-on-chip.\\n\\nShe got the PhD in Bioengineering at Politecnico di Milano in April 2015 on the development of microfluidic platforms for 3D cell culture. She concluded 4 years of PostDoc fellowship at the Department of Biomedicine of the University Hospital of Basel, working in the establishment of in vitro models of cartilage development and pathologies. She came back to Politecnico di Milano as PostDoctoral fellow, as beneficiary of the European Project MSCA Individual Fellowship and of a project for young researchers financed by Cariplo Foundation, both aimed at developing a model of joint-on-a-chip for advancing the development of anti-osteoarthritic drugs. She is beneficiary of an Horizon Europe ERC Starting Grant, one of the most prestigious project granted by European Commission to talented young PI, in the field of Organs-on-Chip (OoC) and Artificial Intelligence (AI). She is also active member of the CEN CENLEC Focus Group who drafted the roadmap for OoC standardization. She is co-founder of BiomimX S.r.l., Italian Startup, Spin-off of Politecnico di Milano developer of beating organs-on-chip. She authored more than 40 scientific papers published on international peer-reviewed journals (h index 20), 5 book chapters and she is inventor of 2 patents.\\n\\nHer research focuses on the design and development of organ-on-chip platforms integrating advanced microfluidic technologies, complex cell culture system and artificial intelligence, with the aim of generating physiologically relevant three-dimensional tissue models for applications in disease modelling and drug development.","image":"/images/team/paola-occhetta.jpg","scopusId":"55830511600","orcid":"0000-0002-5758-2019","linkedin":"https://www.linkedin.com/in/paola-occhetta-3041ba48/"}],"Tq":[{"id":1,"name":"Dr. Cecilia Palma","role":"Scientific Project Manager","email":"cecilia.palma@polimi.it","bio":"PhD in Bioengineering from Politecnico di Milano, specializing in organs-on-chip for joint disorders. Currently Scientific Project Manager at MiMic Lab, coordinating national and European collaborative projects.","bioFull":"Cecilia Palma holds a PhD in Bioengineering from Politecnico di Milano, where she specialized in the development of organs-on-chip to investigate the mechanobiological mechanisms underlying joint disorders. Her doctoral research was carried out in close collaboration with clinical and industrial partners, including Ospedale Galeazzi, Istituto Europeo di Oncologia and BiomimX\xae, and included a visiting period at the Tissue Engineering laboratory of Universit\xe4tsspital Basel (Switzerland).\\n\\nShe is currently Scientific Project Manager at MiMic Lab, where she coordinates national and European collaborative projects. She supports proposal preparation, project planning and reporting, while closely monitoring the scientific progress of the activities to ensure alignment between engineers, biologists, clinicians, and industry partners. She also contributes to outreach activities aimed at maximizing project impact.","image":"/images/team/cecilia-palma.jpg","scopusId":"57218566228","orcid":"0000-0001-9517-1803"},{"id":2,"name":"Dr. Alberto Mantegazza","role":"Assistant Professor","email":"alberto.mantegazza@polimi.it","bio":"Assistant Professor at DEIB, Politecnico di Milano. His research centers on Organs-on-Chip technologies and microscale fluid dynamics, with a focus on smart mechanically active platforms.","bioFull":"Alberto Mantegazza earned his B.Sc. and M.Sc. in Biomedical Engineering from Politecnico di Milano and completed his Ph.D. at the University of Bern, where he investigated red blood cell partitioning in artificial microvascular networks. He then conducted postdoctoral research at Penn State University on numerical modeling of red blood cell damage in medical devices, followed by work at Politecnico di Bari developing fluid‑structure‑interaction models for microfluidic cell‑sorting applications. In 2024, he joined the MiMic Lab at Politecnico di Milano as a postdoctoral fellow focusing on smart mechanically active Organs‑on‑Chip platforms. His research centers on Organs‑on‑Chip technologies and microscale fluid dynamics.","image":"/images/team/alberto-mantegazza.jpg","scopusId":"57213067936","orcid":"0000-0001-5177-8240"},{"id":3,"name":"Stefania Brambilla","role":"Lab Manager","email":"stefania.brambilla@polimi.it","bio":"Graduated in Biology Applied to Biomedical Research at the University of Milan. Lab Manager at MiMic Lab, responsible for daily research activities, laboratory organization, inventory management and procurement.","bioFull":"Stefania graduated in 2020 in Biology Applied to Biomedical Research in University of Milan, studying lipid profile alterations in neurological disorders, with a focus on glioblastoma. She later continued her research on lipid-mediated drug resistance in glioblastoma. In 2022, she joined the Cell and Tissue Engineering Laboratory at Ospedale Galeazzi–Sant\'Ambrogio, where, under the guidance of Dr. Matteo Moretti, she worked with organ-on-chip systems and developed an osteochondral interface model of osteoarthritis. She also contributed to projects on mesenchymal cell bystander effects and vascularized microfluidic devices during a research period at the Vascular Physiology Laboratory (University of Milan). She is currently a Lab Technician at the MiMic Lab where she manages daily research activities and is responsible for laboratory organization, including inventory management and procurement.","image":"/images/team/stefania-brambilla.jpg","scopusId":"58578734400","orcid":""},{"id":4,"name":"Dr. Mattia Ballerini","role":"PostDoc Researcher","email":"mattia.ballerini@polimi.it","bio":"PhD cum laude in Bioengineering from Politecnico di Milano. Postdoctoral Fellow at MiMic Lab developing innovative Organ-on-Chip platforms, with a primary focus on cardiac models.","bioFull":"Mattia Ballerini received his Bachelor\'s and Master\'s degrees in Biomedical Engineering from Politecnico di Milano and earned his Ph.D. cum laude in Bioengineering in 2022 from the same institution. His doctoral research at MiMic Lab, in collaboration with the European Institute of Oncology, focused on developing a 3D mechanically active Gut-on-Chip platform to investigate microbiome-driven carcinogenesis and immunotherapy response. He is currently a Postdoctoral Fellow at MiMic Lab, where he develops innovative Organ-on-Chip platforms, with a primary focus on cardiac models while collaborating on projects targeting other organ systems.","image":"/images/team/mattia-ballerini.jpg","scopusId":"57266949500","orcid":""},{"id":5,"name":"Dr. Paola Lagonegro","role":"PostDoc Researcher","email":"paola.lagonegro@polimi.it","bio":"Research focus on advanced microfluidic platforms and organ-on-chip systems.","image":"/images/team/paola-lagonegro.jpg","scopusId":"","orcid":""},{"id":6,"name":"Dr. Rahimeh Atashgah","role":"MSCA Postdoctoral Fellow","email":"rahimeh.bairamiatashgah@polimi.it","bio":"MSCA Postdoctoral Fellow developing nanomedicine therapies using advanced melanoma cancer-on-chip models.","bioFull":"Rahime Atashgah is a MSCA-Postdoctoral Fellow within the Department of Electronics, Information and Bioengineering (DEIB) at Politecnico di Milano (POLIMI). Her current research is at the cutting edge of drug delivery and bioengineering, focusing on the development of nanomedicine therapies using advanced melanoma cancer-on-chip model. She completed her PhD at Tehran University of Medical Sciences, where her doctoral work centered on drug delivery systems and tissue engineering specifically designed for chronic wound healing. Rahime\'s broader research interests lie at the intersection of skin cancer mechanisms and nanomedicine.","image":"/images/team/rahimeh-atashgah.jpg","scopusId":"","orcid":""},{"id":20,"name":"Dr. Sofia Belardinelli","role":"PostDoc Researcher","email":"sofia.belardinelli@polimi.it","bio":"Philosopher of science working on the PHOENIX project, focusing on ethical and epistemological aspects of replacing animal models with organ-on-chip technologies.","image":"/images/team/sofia-belardinelli.jpg","scopusId":"","orcid":""},{"id":7,"name":"Alessandro Cordiale","role":"PhD Student","email":"alessandro.cordiale@polimi.it","bio":"PhD candidate developing microfluidic models of epithelial-endothelial barriers for drug discovery and preclinical testing.","bioFull":"Alessandro Cordiale is a Ph.D. candidate at the Microfluidics and Biomimetic Microsystems Laboratory (MiMic Lab). He obtained both his Bachelor\'s and Master\'s degrees in Biomedical Engineering from Politecnico di Milano. His Master\'s thesis was conducted at the Zentrum f\xfcr Zahnmedizin of the University of Zurich, where he designed and validated an organ-on-chip (OoC) platform to develop a 3D in vitro model of human dental pulp.\\n\\nFollowing graduation, he worked as an R&D Engineer Intern at BiomimX S.r.l. and as a Research Fellow at MiMic Lab, focusing on the design of electronic systems for controlling biological culture parameters and delivering mechanical stimulation in OoC platforms.\\n\\nDuring his doctoral studies, he was awarded a Rocca Fellowship to join the Mechanobiology Lab at Massachusetts Institute of Technology as a visiting Ph.D. student, where he worked on tumor cell intravasation models.\\n\\nHis current research focuses on the development of microfluidic models of epithelial–endothelial barriers to advance drug discovery and preclinical testing.","image":"/images/team/alessandro-cordiale.jpg","scopusId":"","orcid":""},{"id":8,"name":"Giacomo Cretti","role":"PhD Student","email":"giacomo.cretti@polimi.it","bio":"PhD student in Bioengineering at Politecnico di Milano, working on vascularized spheroids and tumor-on-chip systems.","bioFull":"Giacomo Cretti (born 1997) received his Bachelor\'s degree in Materials and Nanotechnology Engineering (2021) and his Master\'s degree in Biomedical Engineering (2022) from Politecnico di Milano. He is currently a PhD student in Bioengineering at Politecnico di Milano, working on vascularized spheroids and tumor-on-chip systems.","image":"/images/team/giacomo-cretti.jpg","scopusId":"","orcid":""},{"id":9,"name":"Elisa Monti","role":"PhD Student","email":"elisa.monti@polimi.it","bio":"PhD candidate investigating signaling pathways altered by cartilage mechanical dysregulation during osteoarthritis in a cartilage-on-chip model.","bioFull":"Elisa Monti is a PhD candidate at the Microfluidic and Biomimetic Microsystems Laboratory (MiMic Lab). She earned her Master Degree in Biomedical Engineering at Politecnico di Milano in 2022, with a thesis on the optimization of a multiorgan-on-chip platform for the investigation of drugs cardiotoxicity. Her current research involves the investigation of signaling pathways altered by cartilage mechanical dysregulation during initiation and progression of osteoarthritis in a cartilage-on-chip model. Concurrently, she studies the impact of mechanical stimulation on the differentiation of mesenchymal stromal cells towards a chondrogenic lineage.","image":"/images/team/elisa-monti.jpg","scopusId":"","orcid":""},{"id":10,"name":"Alessandro Cacioppo","role":"PhD Student","email":"alessandro.cacioppo@polimi.it","bio":"PhD student focused on the development of advanced heart-on-chip models at the MiMic Lab.","bioFull":"Alessandro Cacioppo is a biomedical engineer with a strong academic background in bioengineering and organ-on-chip technologies, currently pursuing a PhD at Politecnico di Milano in the MiMic Lab, focused on the development of advanced heart-on-chip models.","image":"/images/team/alessandro-cacioppo.jpg","scopusId":"","orcid":""},{"id":11,"name":"Bianca Aterini","role":"PhD Student","email":"bianca.aterini@polimi.it","bio":"PhD student developing next-generation lung-on-chip platforms to investigate the impact of environmental hazards on lung health.","bioFull":"Bianca Aterini earned her B.Sc. in Biomedical Engineering from the Universit\xe0 di Pisa and her M.Sc. in Biomedical Engineering, Cells, Tissues and Biotechnologies, from the Politecnico di Milano. She completed an Erasmus+ traineeship at the Tissue Engineering Laboratory of the University Hospital of Basel, where she worked on an intervertebral disc degeneration-on-chip project. In 2023, she joined the MiMic Lab at Politecnico di Milano and is currently pursuing her PhD, focusing on the development of next-generation lung-on-chip platforms to investigate the impact of environmental hazards on lung health.","image":"/images/team/bianca-aterini.jpg","scopusId":"","orcid":""},{"id":12,"name":"Teresa Lucifora","role":"PhD Student","email":"teresa.lucifora@polimi.it","bio":"PhD candidate focused on mechanobiologically driven modeling of idiopathic pulmonary fibrosis within a multicompartment Lung-on-Chip platform.","bioFull":"Teresa Lucifora is a Ph.D. candidate at the Microfluidics and Biomimetic Microsystems Laboratory. She earned her Bachelor\'s and Master\'s degrees in Biomedical Engineering from Politecnico di Milano, completing her thesis as an Exchange Visitor at the Center for Musculoskeletal Regeneration, Houston Methodist Research Institute (Houston, TX), where she engineered microfluidic-derived leukocyte-based biomimetic nanocarriers encapsulating a mutant IDH2 inhibitor for the targeted treatment of osteosarcoma. Since 2023, her doctoral research has focused on mechanobiologically driven modeling of idiopathic pulmonary fibrosis within a multicompartment Lung-on-Chip platform. Her work integrates microfluidics, mechanobiology, and translational bioengineering to establish a predictive human in vitro model for the preclinical evaluation of anti-fibrotic therapies.","image":"/images/team/teresa-lucifora.jpg","scopusId":"","orcid":""},{"id":13,"name":"Sophie V\xe9ronique Materne","role":"PhD Student","email":"sophie.materne@polimi.it","bio":"PhD student developing a mechanically-active cartilage-on-chip model with real-time on-chip monitoring to explore mechanically driven chondrogenesis.","bioFull":"Sophie Materne is a PhD student at the Microfluidic and Biomimetic Microsystems Laboratory at Politecnico di Milano, whose project consists of developing advanced organ-on-chip tools for research on pathophysiological models. More precisely, she is designing a mechanically-active cartilage-on-chip model with real-time on-chip monitoring to explore mechanically driven chondrogenesis.\\n\\nShe earned her bachelor\'s degree in Civil Engineering at Li\xe8ge University in 2021, and then graduated from Li\xe8ge University and Politecnico di Milano in 2024 with a T.I.M.E. double degree in Biomechanical Engineering. For her master\'s thesis, she worked at the Istituto Nazionale dei Tumori di Milano as a research intern in computational modelling and developed a mechanistic computational model of the microvasculature informed by patient-specific characteristics to assess radiotherapy outcomes.","image":"/images/team/sophie-materne.jpg","scopusId":"","orcid":""},{"id":14,"name":"Elia Pennati","role":"PhD Student","email":"elia.pennati@polimi.it","bio":"PhD candidate working on a bone marrow-on-chip microfluidic device for early detection of lung cancer relapses.","bioFull":"Elia Pennati earned his bachelor\'s degree in Biomolecular Sciences and Technology at the University of Trento. For his master\'s degree in Pharmaceutical Biotechnology, he relocated to Bologna in 2019. In April 2021, Elia had the opportunity to join the Life Science Electronics Laboratory at \xc9cole Polytechnique F\xe9d\xe9rale de Lausanne, where he carried out his master\'s thesis internship. During this period, he worked on a microfluidic lab-on-chip device to quantify specific acute kidney injury biomarkers.\\n\\nAfter spending one year in Switzerland, Elia moved to Milan for a fellowship on a project studying the nerve invasion of the pancreatic ductal adenocarcinoma at San Raffaele Hospital.\\n\\nIn May 2024, he joined the MiMic Laboratory of Politecnico di Milano as PhD candidate. His PhD project involves the use of a bone marrow-on-chip microfluidic device for early detection of lung cancer relapses.","image":"/images/team/elia-pennati.jpg","scopusId":"","orcid":""},{"id":15,"name":"Asia Muraca","role":"PhD Student","email":"asia.muraca@polimi.it","bio":"Fascinated by research since childhood, I was drawn to explore the still mysterious world of neuroscience. When I\'m not in the lab, I enjoy experimenting in the kitchen or spending time outdoors, often chasing my next extreme sport adventure.","image":"/images/team/asia-muraca.jpg","scopusId":"","orcid":""},{"id":16,"name":"Marina Pata","role":"PhD Student","email":"marina.pata@polimi.it","bio":"PhD candidate in Bioengineering at DEIB, Politecnico di Milano. Her research focuses on developing a vascularized glioblastoma-on-chip platform to model the tumor microenvironment.","bioFull":"Marina is a PhD candidate in Bioengineering at DEIB, the Department of Electronics, Information and Bioengineering at Politecnico di Milano. She completed her Master\'s degree in Bioengineering at Politecnico di Milano in July 2024. Her current research focuses on developing a vascularized glioblastoma-on-chip platform to model the tumor microenvironment and investigate nanoparticle transport across blood vessels. Her work combines microfluidics, cell biology and advanced in vitro models to better understand drug delivery mechanisms in brain tumors.","image":"/images/team/marina-pata.jpg","scopusId":"","orcid":""},{"id":17,"name":"Sonia Peddio","role":"PhD Student","email":"sonia.peddio@polimi.it","bio":"PhD student working on cardiac and vascular tissue models in collaboration with Politecnico di Milano and Humanitas University.","bioFull":"Sonia Peddio earned her bachelor\'s degree (2022) and master\'s degree (2025) in Biomedical Engineering at Politecnico di Milano. She first joined the MiMic Lab as a master\'s student, developing a microfluidic platform for a hierarchical model of vasculature, and continued her work as a PhD student. Her doctoral program is part of a collaboration between Politecnico di Milano and Humanitas University, where she works at the intersection of engineering and medicine, focusing on cardiac and vascular tissue models for personalized therapies.","image":"/images/team/sonia-peddio.jpg","scopusId":"","orcid":""},{"id":18,"name":"Viola Antonello","role":"PhD Student","email":"viola.antonello@polimi.it","bio":"PhD candidate developing integrated pumping systems for organ-on-chip models to recreate physiological conditions in vitro.","bioFull":"Viola Antonello is a PhD candidate at the Microfluidic and Biomimetic Microsystems Laboratory (MiMic Lab). She obtained her Bachelor\'s degree in Biomedical Engineering from Politecnico di Milano in 2021 and her Master\'s degree in Biomedical Engineering from the same institution in 2025. Her studies focused on bioengineering applications to cells, tissues, and biotechnologies. During her master\'s thesis at the MiMic Lab, she worked on the development and the validation of a micropumping system for a vessel-on-chip model. Her current research focuses on developing integrated pumping systems for various organ-on-chip models to recreate physiological conditions in vitro and enable the controlled delivery of cells and drugs.","image":"/images/team/viola-antonello.jpg","scopusId":"","orcid":""},{"id":19,"name":"Federico Volpato","role":"PhD Student","email":"federico.volpato@polimi.it","bio":"PhD student developing lung-on-chip models for chronic lung diseases, particularly asthma.","bioFull":"Federico Volpato obtained a Bachelor\'s degree in Biotechnology and a Master\'s degree in Medical Biotechnology, with a focus on Personalized Medicine, from the University of Modena and Reggio Emilia. During his Master\'s thesis internship at Chiesi Farmaceutici, he worked on advanced in vitro models, particularly air-liquid interface (ALI) cell cultures, for the study of chronic lung diseases, with a focus on COPD. After graduating, he continued working in the same laboratory before joining the Microfluidics and Biomimetic Microsystems Laboratory (MiMic Lab) in September 2025 as a PhD student, where his research focuses on the development of lung-on-chip models for chronic lung diseases, particularly asthma.","image":"/images/team/federico-volpato.jpg","scopusId":"","orcid":""}]}')}}]);